import{_ as e,o as t,c as s,ae as n}from"./chunks/framework.Dn7Y7LSn.js";const g=JSON.parse('{"title":"What is AdRail?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-adrail.md","filePath":"guide/what-is-adrail.md"}'),r={name:"guide/what-is-adrail.md"};function i(l,a,o,p,d,c){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="what-is-adrail" tabindex="-1">What is AdRail? <a class="header-anchor" href="#what-is-adrail" aria-label="Permalink to &quot;What is AdRail?&quot;">​</a></h1><p>AdRail is the payment layer for agent advertising. While protocols like <a href="https://adcontextprotocol.org" target="_blank" rel="noreferrer">AdCP</a> handle media buying and ad serving, AdRail handles the money.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Traditional advertising payments are broken:</p><ul><li><strong>90-day payment terms</strong> — Publishers wait months to get paid</li><li><strong>Hidden fees</strong> — 32-49% taken by intermediaries</li><li><strong>No transparency</strong> — Publishers don&#39;t know what advertisers actually pay</li><li><strong>Manual reconciliation</strong> — Disputes take weeks to resolve</li><li><strong>Not agent-ready</strong> — Existing systems can&#39;t handle machine-to-machine transactions</li></ul><h2 id="the-solution" tabindex="-1">The Solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The Solution&quot;">​</a></h2><p>AdRail provides:</p><ul><li><strong>Instant payments</strong> — Publishers get paid as impressions are verified</li><li><strong>Transparent fees</strong> — 1% flat fee, fully visible on-chain</li><li><strong>Escrow security</strong> — Advertiser funds locked before campaigns start</li><li><strong>On-chain verification</strong> — Every payment verifiable on Base</li><li><strong>x402 native</strong> — Built for agent-to-agent commerce</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┐     ┌─────────────┐     ┌─────────────┐</span></span>
<span class="line"><span>│  Advertiser │     │   AdRail    │     │  Publisher  │</span></span>
<span class="line"><span>└──────┬──────┘     └──────┬──────┘     └──────┬──────┘</span></span>
<span class="line"><span>       │                   │                   │</span></span>
<span class="line"><span>       │  1. Fund Escrow   │                   │</span></span>
<span class="line"><span>       │  (USDC on Base)   │                   │</span></span>
<span class="line"><span>       │──────────────────&gt;│                   │</span></span>
<span class="line"><span>       │                   │                   │</span></span>
<span class="line"><span>       │                   │  2. Serve Ads     │</span></span>
<span class="line"><span>       │                   │&lt;──────────────────│</span></span>
<span class="line"><span>       │                   │                   │</span></span>
<span class="line"><span>       │                   │  3. Report        │</span></span>
<span class="line"><span>       │                   │  Impressions      │</span></span>
<span class="line"><span>       │                   │&lt;──────────────────│</span></span>
<span class="line"><span>       │                   │                   │</span></span>
<span class="line"><span>       │                   │  4. Verify &amp;      │</span></span>
<span class="line"><span>       │                   │  Pay (USDC)       │</span></span>
<span class="line"><span>       │                   │──────────────────&gt;│</span></span>
<span class="line"><span>       │                   │                   │</span></span></code></pre></div><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Description</th></tr></thead><tbody><tr><td><strong>Publisher</strong></td><td>Site or agent that displays ads and earns revenue</td></tr><tr><td><strong>Advertiser</strong></td><td>Company buying ad impressions</td></tr><tr><td><strong>Escrow</strong></td><td>Locked USDC funds for a campaign</td></tr><tr><td><strong>Impression</strong></td><td>A single ad view, reported in batches</td></tr><tr><td><strong>Settlement</strong></td><td>USDC transfer from escrow to publisher</td></tr></tbody></table><h2 id="built-on" tabindex="-1">Built On <a class="header-anchor" href="#built-on" aria-label="Permalink to &quot;Built On&quot;">​</a></h2><ul><li><strong><a href="https://x402.org" target="_blank" rel="noreferrer">x402</a></strong> — HTTP-native payment protocol</li><li><strong><a href="https://www.circle.com/usdc" target="_blank" rel="noreferrer">USDC</a></strong> — Stable, liquid, widely accepted</li><li><strong><a href="https://base.org" target="_blank" rel="noreferrer">Base</a></strong> — Fast, cheap, Coinbase-backed L2</li><li><strong><a href="https://adcontextprotocol.org" target="_blank" rel="noreferrer">AdCP</a></strong> — Ad Context Protocol for media buying</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/guide/getting-started.html">Getting Started</a> — Set up your account</li><li><a href="/guide/quickstart.html">Quick Start</a> — Make your first API call</li><li><a href="/api/overview.html">API Reference</a> — Full endpoint documentation</li></ul>`,16)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
